/** Frame 2204 -- generated by the template lab from Figma node 538:39073
 *  (Frame 2204). Everything is drawn from the board itself
 *  (FigmaLayers); the slots below are what a designer edits, each in its
 *  board place and stacking order:
 *    copy tied to the brief -- amount, lead, cta/shop-all-sale;
 *    board copy, editable -- flash-sale, text, off, women-s-apparel, summer-apparel, footwear, camp-hike;
 *    photos -- photo, product-cutout/photo, product-cutout/photo-2, product-cutout/photo-3; brand slots -- none.
 *  Text contracts come from each board layer (boardFit). NUDGE (./nudges.ts)
 *  holds the fix loop's per-layer corrections to Figma's render. */
import type { SheetAsset } from '../../../../../sheet/types';
import { Ground } from '../../../../../edit/Editable';
import { Picture } from '../../../../../edit/Picture';
import { ZONE_LIST, photoFor } from '../../../../../model/compose';
import { FigmaLayers, FigmaText, FigmaStroke, FigmaMark, type Slot } from '../../../../../render/figma/FigmaLayers';
import { cropOf, type FigmaLayout } from '../../../../../render/figma/layout';
import board from './layout.json';
import { NUDGE } from './nudges';

/** Which board layer each editable layer is, by the part of its id after the asset's. */
export const FRAME_2204_538_39073_FIGMA = {
  "flash-sale": "538:39077", // text: FLASH SALE
  "amount": "538:39089", // amount: 70
  "text": "538:39092", // text: %
  "off": "538:39093", // text: OFF
  "lead": "538:39095", // lead: UP TO
  "women-s-apparel": "538:39100", // text: Women’s Apparel
  "summer-apparel": "538:39107", // text: Summer Apparel
  "footwear": "538:39114", // text: Footwear
  "camp-hike": "538:39121", // text: Camp & Hike
  "cta/shop-all-sale": "538:39126", // cta: Shop All Sale
  "cat-buttons/cat-7": "538:39097", // pill: CAT 7
  "cat-7/arrow": "538:39101", // graphic: Arrow
  "cat-buttons/cat-8": "538:39104", // pill: CAT 8
  "cat-8/arrow": "538:39108", // graphic: Arrow
  "cat-buttons/cat-6": "538:39111", // pill: CAT 6
  "cat-6/arrow": "538:39115", // graphic: Arrow
  "cat-buttons/cat-1": "538:39118", // pill: CAT 1
  "cat-1/arrow": "538:39122", // graphic: Arrow
  "cta/cta": "538:39125", // pill: CTA
  "product-cutout/photo": "538:39099", // photo: image 3752
  "product-cutout/photo-2": "538:39106", // photo: image 3753
  "product-cutout/photo-3": "538:39120", // photo: image 3726
} as const;

export function Frame2204_538_39073({ asset }: { asset: SheetAsset }) {
  const layout = board as unknown as FigmaLayout, id = asset.id;
  const zone = ZONE_LIST.find(z => z.id === asset.media.photo) ?? photoFor('hike', 0);
  const slots: Record<string, Slot> = {
    [FRAME_2204_538_39073_FIGMA["flash-sale"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/flash-sale`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["amount"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/amount`} contract="lab.amount" layout={layout}
      text={l.text!.chars.replace(/\d+/, (asset.copy.offer ?? '').match(/(\d+)\s*%/)?.[1] ?? (asset.copy.offer ?? '').match(/\d+/)?.[0] ?? '$&')} />,
    [FRAME_2204_538_39073_FIGMA["text"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/text`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["off"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/off`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["lead"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/lead`} contract="lab.lead" layout={layout}
      text={asset.copy.lead ? (l.text!.chars.includes('\u2028') ? asset.copy.lead.replace(/\s+/, '\n') : asset.copy.lead) : l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["women-s-apparel"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/women-s-apparel`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["summer-apparel"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/summer-apparel`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["footwear"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/footwear`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["camp-hike"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/camp-hike`} contract="lab.text" layout={layout}
      text={l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["cta/shop-all-sale"]]: (l, box, n) => <FigmaText l={l} box={box} nudge={n} id={`${id}/cta/shop-all-sale`} contract="lab.cta" layout={layout}
      text={asset.copy.cta || l.text!.chars} />,
    [FRAME_2204_538_39073_FIGMA["cat-buttons/cat-7"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cat-buttons/cat-7/mark`} src="/graphics/named-sale-pill-1073x173-nrkss3.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [FRAME_2204_538_39073_FIGMA["cat-7/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/cat-7/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
    [FRAME_2204_538_39073_FIGMA["cat-buttons/cat-8"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cat-buttons/cat-8/mark`} src="/graphics/named-sale-pill-1073x173-nrkss3.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [FRAME_2204_538_39073_FIGMA["cat-8/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/cat-8/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
    [FRAME_2204_538_39073_FIGMA["cat-buttons/cat-6"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cat-buttons/cat-6/mark`} src="/graphics/named-sale-pill-1073x173-nrkss3.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [FRAME_2204_538_39073_FIGMA["cat-6/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/cat-6/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
    [FRAME_2204_538_39073_FIGMA["cat-buttons/cat-1"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cat-buttons/cat-1/mark`} src="/graphics/named-sale-pill-1073x173-nrkss3.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [FRAME_2204_538_39073_FIGMA["cat-1/arrow"]]: (l, box) => <FigmaMark l={l} box={box} id={`${id}/cat-1/arrow/mark`} src="/graphics/bump2-arrow.svg"
      fill="#FFFFFF" pad={[0.05707738777210708, 0.08684627575277339]} layout={layout} />,
    [FRAME_2204_538_39073_FIGMA["cta/cta"]]: (l, box, _n, board) => <>
      <FigmaMark l={l} box={box} id={`${id}/cta/cta/mark`} src="/graphics/named-sale-pill-546x120-o8upvx.svg" fill="#F14222" layout={layout} />
      {board({ bare: true })}
    </>,
    [FRAME_2204_538_39073_FIGMA["product-cutout/photo"]]: (l, box) => {
      const img = l.images?.[0] && layout.assets?.[l.images[0].ref];
      const crop = img && l.crop ? cropOf(l.crop, [l.w, l.h], [img.w, img.h]) : undefined;
      // The board's fade, kept for whatever photo fills the slot.
      const fade = l.images?.[0]?.opacity;
      return <>
        <Picture id={`${id}/product-cutout/photo`} zone={zone} initialSrc={img?.src} slot
          focus={crop?.focus} initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={l.crop}
          style={{ ...box, overflow: 'hidden', borderRadius: l.radius, clipPath: l.path ? `path("${l.path}")` : undefined, opacity: fade ?? box.opacity }} />
        <FigmaStroke l={l} box={box} />
      </>;
    },
    [FRAME_2204_538_39073_FIGMA["product-cutout/photo-2"]]: (l, box) => {
      const img = l.images?.[0] && layout.assets?.[l.images[0].ref];
      const crop = img && l.crop ? cropOf(l.crop, [l.w, l.h], [img.w, img.h]) : undefined;
      // The board's fade, kept for whatever photo fills the slot.
      const fade = l.images?.[0]?.opacity;
      return <>
        <Picture id={`${id}/product-cutout/photo-2`} zone={zone} initialSrc={img?.src} slot
          focus={crop?.focus} initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={l.crop}
          style={{ ...box, overflow: 'hidden', borderRadius: l.radius, clipPath: l.path ? `path("${l.path}")` : undefined, opacity: fade ?? box.opacity }} />
        <FigmaStroke l={l} box={box} />
      </>;
    },
    [FRAME_2204_538_39073_FIGMA["product-cutout/photo-3"]]: (l, box) => {
      const img = l.images?.[0] && layout.assets?.[l.images[0].ref];
      const crop = img && l.crop ? cropOf(l.crop, [l.w, l.h], [img.w, img.h]) : undefined;
      // The board's fade, kept for whatever photo fills the slot.
      const fade = l.images?.[0]?.opacity;
      return <>
        <Picture id={`${id}/product-cutout/photo-3`} zone={zone} initialSrc={img?.src} slot
          focus={crop?.focus} initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={l.crop}
          style={{ ...box, overflow: 'hidden', borderRadius: l.radius, clipPath: l.path ? `path("${l.path}")` : undefined, opacity: fade ?? box.opacity }} />
        <FigmaStroke l={l} box={box} />
      </>;
    },
  };
  const [w, h] = layout.size;
  // The frame's own photo, swappable, under every layer (and not drawn again by FigmaLayers).
  const photo = layout.frame.images?.[0] && layout.assets?.[layout.frame.images[0].ref];
  const crop = photo && layout.frame.crop ? cropOf(layout.frame.crop, [w, h], [photo.w, photo.h]) : undefined;
  const drawn = { ...layout, frame: { ...layout.frame, paints: layout.frame.paints?.filter(p => p.type !== 'IMAGE') } };
  // data-figma-compiled: the studio's Figma export reads a compiled board's way (toLayers).
  return <Ground id={`${id}/fill`} className="sheet" data-figma-compiled="" style={{ width: w, height: h, position: 'relative', overflow: 'hidden', background: '#fff' }}>
    <Picture id={`${id}/photo`} zone={zone} initialSrc={photo?.src} slot focus={crop?.focus}
      initialScale={crop?.initialScale} initialRotate={crop?.rotate} initialCrop={layout.frame.crop}
      style={{ position: 'absolute', inset: 0 }} />
    <FigmaLayers layout={drawn} slots={slots} nudges={NUDGE} />
  </Ground>;
}
